// WF-009 — Intent Classifier
// Detecta la intención del mensaje entrante y asigna la respuesta automática.

const item = $input.first();
const rawBody = (item.json.body?.body || item.json.body || '').toLowerCase().trim();
const phone   = item.json.body?.phone   || item.json.phone   || '';
const inboundId = item.json.body?.inbound_message_id || item.json.inbound_message_id || null;

// ── Intents ordenados por prioridad ──────────────────────────────────────────
const INTENTS = [
  {
    key: 'precios',
    pattern: /precio|costo|cu[áa]nto/,
    response: [
      '💰 *Precios y planes*',
      '',
      'Actualmente contamos con los siguientes planes:',
      '• Plan Básico: consultanos para el precio actualizado',
      '• Plan Pro: a medida según volumen',
      '• Plan Enterprise: a convenir',
      '',
      'Para recibir una cotización personalizada, respondé con tu nombre y empresa.',
      '¡Estaremos en contacto enseguida! 😊'
    ].join('\n')
  },
  {
    key: 'info',
    pattern: /info|informaci[oó]n|qu[eé] es/,
    response: [
      '📋 *¿Quiénes somos?*',
      '',
      'Somos una plataforma de automatización de comunicaciones vía WhatsApp para empresas en LATAM.',
      '',
      'Automatizamos:',
      '✅ Atención al cliente',
      '✅ Notificaciones de transacciones',
      '✅ Campañas de retención',
      '',
      '¿Querés saber más? Escribí *precio* o pedí hablar con un asesor escribiendo *asesor*. 😊'
    ].join('\n')
  },
  {
    key: 'horario',
    pattern: /horario|cu[áa]ndo|\bhora\b/,
    response: [
      '🕐 *Horarios de atención*',
      '',
      '📅 Lunes a Viernes: 9:00 – 18:00 hs (ART)',
      '📅 Sábados: 10:00 – 14:00 hs (ART)',
      '',
      'Fuera de ese horario respondemos el primer día hábil.',
      '',
      '¿Necesitás algo urgente? Escribí *asesor* y te conectamos. 🙌'
    ].join('\n')
  },
  {
    key: 'humano',
    pattern: /humano|persona|asesor/,
    response: [
      '👤 *¡Enseguida te conectamos!*',
      '',
      'Un asesor se va a comunicar con vos a la brevedad.',
      '',
      'Horario de atención: Lunes a Viernes, 9:00 – 18:00 hs (ART).',
      '',
      'Si es urgente también podés escribirnos a: contacto@plataforma.com ✉️'
    ].join('\n')
  }
];

// ── Fallback genérico ─────────────────────────────────────────────────────────
const GENERIC_RESPONSE = [
  '👋 ¡Hola! Recibimos tu mensaje.',
  '',
  'Podemos ayudarte con:',
  '• *precio*   – consultar planes y precios',
  '• *info*     – conocer más sobre nosotros',
  '• *horario*  – ver horarios de atención',
  '• *asesor*   – hablar con una persona',
  '',
  '¡Escribí la palabra que mejor describa tu consulta! 😊'
].join('\n');

// ── Clasificación ─────────────────────────────────────────────────────────────
let intent = 'generico';
let response_text = GENERIC_RESPONSE;

for (const { key, pattern, response } of INTENTS) {
  if (pattern.test(rawBody)) {
    intent = key;
    response_text = response;
    break;
  }
}

return [{
  json: {
    phone,
    raw_body: rawBody,
    intent,
    response_text,
    inbound_message_id: inboundId
  }
}];
